/** Canonical Survival Duplifier capture/apply/Undo through installed formed-arm owners. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearCopiedSettingsChecks {
    private static final BlockPos SOURCE=new BlockPos(40,110,0),TARGET=SOURCE.east(8);private static ServerLevel world;private static Actor actor;private static boolean running;private static int stage,ticks,checks;private static CompoundTag before;private static UUID identity;private static ItemStack clipboard;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel world){super(world,new com.mojang.authlib.GameProfile(new UUID(0,2211492),"GearCopy"));}}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native gear copied settings stage="+stage+": "+why);}
    private static NativeGearEntity root(BlockPos at){var root=NativeGearFormation.at(world,at);need(root!=null&&!root.inert()&&root.controller(),"healthy source assembly "+at);return root;}
    private static void position(BlockPos root){actor.setPos(root.getX()+.5,root.getY()+.5,root.getZ()-3);actor.setYRot(0);}
    private static boolean use(BlockPos at){position(at);return actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at).add(0,0,-.5),Direction.NORTH,at,false)).consumesAction();}
    private static void put(BlockPos root,Direction mount,NativeGearDefinition kind){world.setBlock(root.relative(mount.getOpposite()),Blocks.STONE.defaultBlockState(),3);var arms=new ItemStack(NativeGearBindings.ITEMS.get(kind.id),2);actor.setItemInHand(InteractionHand.MAIN_HAND,arms);position(root);for(int n=0;n<2;n++){var support=root.relative(mount,n-1);need(actor.gameMode.useItemOn(actor,world,arms,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(mount.getNormal()).scale(.5)),mount,support,false)).consumesAction(),"actual supported Survival arm sections");}need(arms.isEmpty(),"two section items consumed");var ski=new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.SKI.id));actor.setItemInHand(InteractionHand.MAIN_HAND,ski);var support=root.relative(mount);need(actor.gameMode.useItemOn(actor,world,ski,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(mount.getNormal()).scale(.5)),mount,support,false)).consumesAction()&&ski.isEmpty(),"real Ski formation item");}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!Boolean.getBoolean("vandorlabs.gearCopyCheck"))return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);for(int x=1;x<=4;x++)for(int z=-1;z<=1;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}for(int x=34;x<=55;x++)for(int y=104;y<=116;y++)for(int z=-6;z<=6;z++)world.setBlock(new BlockPos(x,y,z),y==104?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);for(int facing=0;facing<4;facing++){var at=SOURCE.offset(facing*3,0,12);world.setBlock(at.above(),Blocks.STONE.defaultBlockState(),3);position(at);actor.setYRot(facing*90);var plain=new ItemStack(NativeGearBindings.ITEMS.get(NativeGearDefinition.ROTATING.id));actor.setItemInHand(InteractionHand.MAIN_HAND,plain);need(actor.gameMode.useItemOn(actor,world,plain,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at.above()).add(0,-.5,0),Direction.DOWN,at.above(),false)).consumesAction(),"plain item cardinal placement");var placed=NativeGearFormation.at(world,at);need(placed.settings().direction()==com.vandorlabs.gear.core.GearMotion.Direction.valueOf(placed.getBlockState().getValue(NativeGearBlock.FACING).name()).ordinal(),"plain item inherits authored cardinal facing");}put(SOURCE,Direction.DOWN,NativeGearDefinition.ROTATING);put(TARGET,Direction.EAST,NativeGearDefinition.LARGE_ROTATING);running=true;}catch(Throwable failure){fail(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<120,"bounded deferred formation/configuration");if(stage==0){var source=NativeGearFormation.at(world,SOURCE);var target=NativeGearFormation.at(world,TARGET);if(source==null||target==null||!source.controller()||!target.controller()||source.assembly().kind()!=com.vandorlabs.gear.core.GearTopology.FootKind.SKI||target.assembly().kind()!=com.vandorlabs.gear.core.GearTopology.FootKind.SKI)return;var choices=source.settings().choices();choices.putInt("FootFacing",Direction.WEST.get2DDataValue());choices.putBoolean("MiddleHinge",true);choices.putInt("Direction",1);choices.putBoolean("RotatePayload",true);choices.putInt("JoinRange",8);choices.putInt("LoadHeight",2);choices.putInt("Trigger",2);choices.putString("Channels","7, 23");choices.putBoolean("LegacyAnyChannels",true);need(source.configure(NativeGearSettings.readChoices(choices),true),"configure resting source foot/middle/redstone choices");source.authorize(actor);before=NativeGearCopiedSettings.capture(target.settings());identity=target.identity();target.getPersistentData().putByteArray("CopyPrivateOpaque",new byte[256]);clipboard=new ItemStack(NativeCopifierRegistrations.ITEM.get());actor.setItemInHand(InteractionHand.MAIN_HAND,clipboard);actor.setShiftKeyDown(true);need(use(SOURCE.below()),"canonical Survival Duplifier shift capture through child");actor.setShiftKeyDown(false);var captured=NativeCopifierClipboard.settings(NativeCopifierItem.data(clipboard));need(captured!=null&&captured.equals(NativeGearCopiedSettings.capture(source.settings())),"Source-compatible semantic projection");need(captured.getAllKeys().equals(Set.of("modular_arm_settings","redstone_trigger","redstone_channel"))&&!captured.toString().contains("NativeGear")&&!captured.toString().contains("CopyPrivateOpaque")&&!captured.getCompound("modular_arm_settings").contains("Deployed")&&!captured.getCompound("modular_arm_settings").contains("Channels"),"clipboard excludes placement/phase/identity/opaque/resource ownership");need(use(TARGET.relative(Direction.EAST)),"actual Duplifier apply through Large arm child");need(NativeGearCopiedSettings.capture(target.settings()).equals(captured),"FootFacing/MiddleHinge/range/angles/redstone bank copied");need(target.identity().equals(identity)&&target.mount()==Direction.EAST&&target.target()&&target.getPersistentData().getByteArray("CopyPrivateOpaque").length==256,"native target identity/mount/phase/private metadata retained");stage=1;return;}
        if(stage==1){var target=root(TARGET);need(NativeCopifierUndo.undo(actor),"existing copied-settings Undo");need(before.equals(NativeGearCopiedSettings.capture(target.settings()))&&target.identity().equals(identity)&&target.mount()==Direction.EAST,"Undo restores settings only");var values=NativeCopifierClipboard.settings(NativeCopifierItem.data(clipboard));var malformed=values.copy();malformed.getCompound("modular_arm_settings").putInt("FootFacing",8);var saved=target.saveWithFullMetadata(world.registryAccess());need(!NativeCopifierHousingWorld.applySingle(world,TARGET,actor,Direction.NORTH,malformed)&&saved.equals(target.saveWithFullMetadata(world.registryAccess())),"malformed arm field rejected before mutation");var filtered=values.copy();filtered.remove("redstone_channel");filtered.remove("redstone_trigger");var plan=NativeGearCopiedSettings.prepare(target.settings(),filtered);need(plan.settings().trigger()==target.settings().trigger()&&plan.settings().channels().equals(target.settings().channels())&&plan.settings().legacyAnyChannels()==target.settings().legacyAnyChannels(),"arm-only mask preserves independent redstone choices");actor.setGameMode(GameType.SPECTATOR);need(!NativeCopifierHousingWorld.applySingle(world,TARGET,actor,Direction.NORTH,values),"spectator forbidden");actor.setGameMode(GameType.SURVIVAL);need(target.command(false),"activate target before moving-shape guard");stage=2;return;}
        if(stage==2){var target=root(TARGET);if(target.progress()==1)return;var values=NativeCopifierClipboard.settings(NativeCopifierItem.data(clipboard));var saved=target.saveWithFullMetadata(world.registryAccess());position(TARGET);need(!NativeCopifierHousingWorld.applySingle(world,TARGET,actor,Direction.NORTH,values)&&saved.equals(target.saveWithFullMetadata(world.registryAccess())),"moving shape copy refuses without ownership/setting mutation");System.out.println("[vandorlabs][gear-copy] PASS checks="+checks+" canonicalSurvivalDuplifier/childOwners/regularLarge/mountPreserved/FootFacing/MiddleHinge/redstone/Undo/malformed/mask/movingGuard");running=false;event.getServer().halt(false);}
    }catch(Throwable failure){fail(failure);}}
    private static void fail(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-copy] FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
